# Offset-based cursor: new orders shift the pages.
perl -0pi -e 's|  app\.get\("/orders", async \(_req, res\) => \{.*?\n  \}\);\n|  app.get("/orders", async (req, res) => {\n    const offset = req.query.cursor ? Number(Buffer.from(String(req.query.cursor), "base64url").toString()) : 0;\n    if (!Number.isInteger(offset) \|\| offset < 0) return sendError(res, 400, "bad_cursor", "Invalid cursor");\n    const { rows } = await pool.query(\n      "select id, status, total_cents, created_at from orders where user_id = \$1 order by created_at desc, id desc limit 21 offset \$2",\n      [res.locals.user.id, offset],\n    );\n    const nextCursor = rows.length > 20 ? Buffer.from(String(offset + 20)).toString("base64url") : null;\n    res.json({ orders: rows.slice(0, 20), nextCursor });\n  });\n|s' src/app.ts
grep -q nextCursor src/app.ts
